:root{
  --bg:#F5F2ED;
  --bg-2:#EFE9E1;
  --ink:#1A1A1A;
  --muted:#5A554F;
  --hair:#D8D0C6;
  --accent:#B26A4A;
  --accent-2:#7A8B6A;
  --shadow: 0 20px 60px rgba(26,26,26,.08);

  --container: 1160px;
  --gutter: clamp(18px, 4vw, 54px);
  --radius: 18px;

  --serif: "Playfair Display", Georgia, "Times New Roman", serif;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}

*{box-sizing:border-box;}
html,body{height:100%;}
html{scroll-behavior:smooth;}
body{
  margin:0;
  background:var(--bg);
  color:var(--ink);
  font-family:var(--sans);
  line-height:1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection{background: rgba(178,106,74,.22);}

a{color:inherit; text-decoration:none;}
a:hover{opacity:.86;}
a:focus-visible, button:focus-visible{outline: 3px solid rgba(178,106,74,.35); outline-offset: 3px; border-radius: 10px;}

.container{max-width:var(--container); margin:0 auto; padding:0 var(--gutter);}

.skip-link{
  position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden;
}
.skip-link:focus{left: var(--gutter); top: 16px; width:auto; height:auto; padding: 10px 12px; background: var(--bg-2); border:1px solid var(--hair); border-radius: 10px; z-index: 10000;}

/* Header / Nav */
.site-header{
  position: sticky;
  top: 0;
  z-index: 1000;
  backdrop-filter: blur(10px);
  background: color-mix(in srgb, var(--bg) 86%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--hair) 70%, transparent);
}
.header-inner{
  display:flex;
  align-items:center;
  justify-content:space-between;
  padding: 18px var(--gutter);
  max-width: var(--container);
  margin: 0 auto;
}

.brand{
  font-family: var(--serif);
  font-weight: 700;
  letter-spacing: -0.02em;
  font-size: 20px;
}
.brand .dot{color: var(--accent);}

.nav{
  display:flex;
  align-items:center;
  gap: 18px;
}
.nav a{
  font-size: 14px;
  letter-spacing: 0.02em;
}
.nav a[aria-current="page"]{opacity: .65;}

.hamburger{
  display:none;
  background: transparent;
  border: 1px solid var(--hair);
  border-radius: 999px;
  padding: 10px 12px;
  color: var(--ink);
  cursor:pointer;
  min-width: 44px;
  min-height: 44px;
}
.hamburger .bars{display:flex; flex-direction:column; gap:6px;}
.hamburger .bar{width:18px; height:1.5px; background: var(--ink); border-radius: 10px; opacity:.9;}

/* Overlay menu */
.overlay{
  position: fixed;
  inset: 0;
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  backdrop-filter: blur(16px);
  z-index: 2000;
  display:none;
}
.overlay[data-open="true"]{display:block;}
.overlay-inner{
  height: 100%;
  display:flex;
  flex-direction:column;
  justify-content:space-between;
  padding: calc(18px + env(safe-area-inset-top)) var(--gutter) calc(18px + env(safe-area-inset-bottom));
  max-width: var(--container);
  margin: 0 auto;
}
.overlay-top{display:flex; align-items:center; justify-content:space-between;}
.overlay-nav{margin-top: 48px; display:flex; flex-direction:column; gap: 18px;}
.overlay-nav a{
  font-family: var(--serif);
  font-weight: 700;
  font-size: clamp(34px, 7vw, 64px);
  letter-spacing: -0.03em;
  line-height: 1.02;
}
.overlay-foot{font-size: 13px; color: var(--muted); max-width: 52ch;}

/* Typography */
.h1{
  font-family: var(--serif);
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 0.98;
  font-size: clamp(42px, 6.2vw, 84px);
  margin: 0;
}
.h2{
  font-family: var(--serif);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.06;
  font-size: clamp(30px, 3.2vw, 44px);
  margin: 0;
}
.eyebrow{
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 12px;
  color: var(--muted);
}
.lede{font-size: 16px; color: var(--muted); max-width: 64ch; margin: 14px 0 0;}

.section{padding: clamp(46px, 6vw, 90px) 0;}

.rule{height:1px; background: var(--hair);}

/* Home hero layout */
.hero-grid{
  display:grid;
  grid-template-columns: 1.2fr .8fr;
  gap: clamp(18px, 5vw, 56px);
  align-items:end;
}
.hero-aside{
  padding-left: clamp(0px, 4vw, 40px);
  border-left: 1px solid color-mix(in srgb, var(--hair) 70%, transparent);
}
.hero-aside p{margin:0; color: var(--muted); max-width: 32ch;}

/* Media showcase */
.media-showcase{
  display:grid;
  grid-template-columns: 1fr 1.1fr .9fr;
  gap: 14px;
  align-items:stretch;
}
.media-block{
  border-radius: var(--radius);
  border: 1px solid color-mix(in srgb, var(--hair) 72%, transparent);
  min-height: clamp(240px, 38vw, 420px);
  box-shadow: 0 1px 0 rgba(26,26,26,.02);
  position:relative;
  overflow:hidden;
}
.media-block::after{
  content:"";
  position:absolute;
  inset:0;
  background: radial-gradient(900px 260px at 10% 10%, rgba(255,255,255,.18), transparent 55%),
              radial-gradient(700px 200px at 90% 60%, rgba(255,255,255,.12), transparent 60%);
  mix-blend-mode: overlay;
  pointer-events:none;
}
.media-caption{position:absolute; left:16px; bottom:14px; font-size: 12px; letter-spacing:.05em; text-transform: uppercase; color: rgba(26,26,26,.72);}

.block-sand{background:#D9C5A6;}
.block-terracotta{background:#C98060;}
.block-sage{background:#8A9B7B;}

/* Marquee */
.marquee{padding: 22px 0; border-top: 1px solid var(--hair); border-bottom: 1px solid var(--hair); background: color-mix(in srgb, var(--bg-2) 65%, transparent); overflow:hidden;}
.marquee-row{display:flex; gap: 22px; align-items:center; white-space:nowrap; will-change: transform;}
.marquee-row .item{font-family: var(--serif); font-weight: 600; font-size: clamp(18px, 2.2vw, 26px); letter-spacing: -0.02em;}
.marquee-row .sep{opacity:.42;}
.marquee-track{display:flex; width:max-content;}

@keyframes marquee-left{0%{transform: translateX(0);}100%{transform: translateX(-50%);}}
@keyframes marquee-right{0%{transform: translateX(-50%);}100%{transform: translateX(0);}}

.marquee-track[data-dir="left"]{animation: marquee-left var(--dur, 26s) linear infinite;}
.marquee-track[data-dir="right"]{animation: marquee-right var(--dur, 28s) linear infinite;}

@media (prefers-reduced-motion: reduce){
  .marquee-track{animation: none !important; transform:none !important;}
  .overlay{backdrop-filter:none;}
}

/* About */
.about-grid{display:grid; grid-template-columns: .75fr 1.25fr; gap: clamp(18px, 5vw, 64px);}
.about-body{max-width: 80ch;}
.about-body p{margin:0 0 16px; color: var(--muted);}

/* Services */
.kicker{max-width: 70ch; color: var(--muted);}
.service-grid{display:grid; grid-template-columns: .9fr 1.1fr; gap: clamp(18px, 5vw, 64px);}
.service-list{display:flex; flex-direction:column; gap: 18px;}
.service-card{padding: 18px 18px 16px; border: 1px solid var(--hair); border-radius: var(--radius); background: color-mix(in srgb, var(--bg) 82%, white 18%);}
.service-card h3{font-family: var(--serif); font-size: 24px; margin: 0 0 8px; letter-spacing: -0.02em;}
.service-card p{margin:0; color: var(--muted);}

/* Clients grid */
.clients-hero{display:grid; grid-template-columns: 1fr 1fr; gap: clamp(18px, 5vw, 64px); align-items:end;}
.clients-grid{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 26px 22px; margin-top: 28px;}
.client-card{padding: 18px 18px 14px; border: 1px solid color-mix(in srgb, var(--hair) 76%, transparent); border-radius: var(--radius); background: color-mix(in srgb, var(--bg) 80%, white 20%);}
.client-card h3{font-family: var(--serif); margin:0 0 8px; font-size: 22px; letter-spacing:-0.02em;}
.client-card p{margin:0; color: var(--muted); font-size: 14.5px;}

/* Founder letter */
.letter-wrap{max-width: 74ch; margin: 0 auto;}
.letter-head{margin-bottom: 26px;}
.letter-title{font-family: var(--serif); font-weight: 700; font-size: clamp(44px, 5.2vw, 74px); letter-spacing:-0.045em; line-height: 0.98; margin:0;}
.letter-sub{margin: 14px 0 0; color: var(--muted); max-width: 60ch;}
.letter-body{font-size: 17px; line-height: 1.85; color: color-mix(in srgb, var(--ink) 92%, var(--muted));}
.letter-body p{margin: 0 0 18px;}
.letter-body p:first-child::first-letter{
  font-family: var(--serif);
  font-weight: 700;
  float:left;
  font-size: 3.2em;
  line-height: .92;
  padding-right: 10px;
  padding-top: 6px;
}
.letter-sig{margin-top: 26px; padding-top: 18px; border-top: 1px solid var(--hair); color: var(--muted); font-size: 14px;}

/* Contact */
.contact-hero{min-height: calc(100dvh - 72px); display:flex; flex-direction:column; justify-content:center; padding: clamp(34px, 7vw, 80px) 0;}
.contact-title{font-family: var(--serif); font-weight: 700; letter-spacing: -0.06em; line-height: 0.88; font-size: clamp(72px, 12vw, 168px); margin:0;}
.contact-links{margin-top: 20px; display:flex; gap: 18px; flex-wrap:wrap;}
.contact-links a{font-size: 14px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); padding: 10px 12px; border: 1px solid var(--hair); border-radius: 999px; min-height: 44px; display:inline-flex; align-items:center;}

/* Footer */
.footer{padding: 36px 0; color: var(--muted); font-size: 13px;}
.footer-inner{display:flex; align-items:flex-start; justify-content:space-between; gap: 18px; border-top: 1px solid var(--hair); padding-top: 18px;}

/* Responsive */
@media (max-width: 900px){
  .nav{display:none;}
  .hamburger{display:inline-flex; align-items:center; justify-content:center;}
  .hero-grid{grid-template-columns: 1fr;}
  .hero-aside{border-left: none; padding-left: 0; border-top: 1px solid color-mix(in srgb, var(--hair) 70%, transparent); padding-top: 16px;}
  .media-showcase{grid-template-columns: 1fr;}
  .about-grid{grid-template-columns: 1fr;}
  .service-grid{grid-template-columns: 1fr;}
  .clients-hero{grid-template-columns: 1fr;}
  .clients-grid{grid-template-columns: 1fr;}
  .header-inner{padding: 16px var(--gutter);}
}
EOF

